func New(executor nook.Executor) *Client {
	client := &Client{
		executor: executor,
	}
	client.App = &AppClient{
		client: client,
	}
	client.Delivery = &DeliveryClient{
		client: client,
	}
	client.Event = &EventClient{
		client: client,
	}
	client.FreeDelivery = &FreeDeliveryClient{
		client: client,
	}
	client.FreeMonitor = &FreeMonitorClient{
		client: client,
	}
	client.FreeOffer = &FreeOfferClient{
		client: client,
	}
	client.FreeSubscription = &FreeSubscriptionClient{
		client: client,
	}
	client.Observation = &ObservationClient{
		client: client,
	}
	client.Rule = &RuleClient{
		client: client,
	}
	client.Target = &TargetClient{
		client: client,
	}

	return client
}

func (c *Client) SQL() nook.Executor {
	return c.executor
}

// WithTx commits on success and rolls back on failure. Nested calls use savepoints.
func (c *Client) WithTx(ctx context.Context, fn func(*Client) error) error {
	return nook.Atomic(ctx, c.executor, func(executor nook.Executor) error {
		return fn(New(executor))
	})
}

func (c *AppClient) Query() AppQuery {
	return AppQuery{
		client: c.client,
		limit:  -1,
	}
}

func (c *AppClient) Get(ctx context.Context, id int64) (*App, error) {
	return c.Query().Get(ctx, id)
}

func (q AppQuery) Where(predicates ...nook.Predicate[App]) AppQuery {
	q.predicates = append(append([]nook.Predicate[App]{}, q.predicates...), predicates...)

	return q
}

func (q AppQuery) OrderBy(order ...nook.Order[App]) AppQuery {
	q.order = append(append([]nook.Order[App]{}, q.order...), order...)

	return q
}

func (q AppQuery) Limit(limit int) AppQuery {
	q.limit = max(0, limit)

	return q
}

func (q AppQuery) Get(ctx context.Context, id int64) (*App, error) {
	return q.Where(AppColumns.ID.Eq(id)).Only(ctx)
}

func (q AppQuery) First(ctx context.Context) (*App, error) {
	items, err := q.Limit(1).All(ctx)
	if err != nil {
		return nil, err
	}

	if len(items) == 0 {
		return nil, sql.ErrNoRows
	}

	return items[0], nil
}

// Only checks cardinality independently of an existing Limit.
func (q AppQuery) Only(ctx context.Context) (*App, error) {
	items, err := q.Limit(2).All(ctx)
	if err != nil {
		return nil, err
	}

	if len(items) == 0 {
		return nil, sql.ErrNoRows
	}

	if len(items) != 1 {
		return nil, nook.ErrNotSingular
	}

	return items[0], nil
}

func (q AppQuery) Count(ctx context.Context) (int64, error) {
	query, args := q.QuerySQL("count(*)")
	var count int64
	err := nook.ReadExecutor(q.client.executor).QueryRowContext(ctx, query, args...).Scan(&count)

	return count, err
}

func (q AppQuery) Exists(ctx context.Context) (bool, error) {
	query, args := q.QuerySQL("1")
	var exists bool
	err := nook.ReadExecutor(q.client.executor).QueryRowContext(ctx, "SELECT EXISTS("+query+")", args...).Scan(&exists)

	return exists, err
}

func (q AppQuery) QuerySQL(fields string) (string, []any) {
	return nook.QuerySQL("apps", fields, q.predicates, nil, -1)
}

func (q AppQuery) SQL() nook.Executor {
	return nook.ReadExecutor(q.client.executor)
}

func (q AppQuery) QueryModel() *App {
	return nil
}

func (q AppQuery) All(ctx context.Context) ([]*App, error) {
	items, err := nook.SelectAll(ctx, nook.ReadExecutor(q.client.executor), "apps", "\"id\", \"name\", \"type\", \"last_modified\", \"price_change_number\", \"updated_at\", \"name_fold\"", q.predicates, q.order, q.limit, scanApp)
	if err != nil {
		return nil, err
	}
	if err := q.loadRelations(ctx, items); err != nil {
		return nil, err
	}

	return items, nil
}

func (q AppQuery) loadRelations(ctx context.Context, items []*App) error {

	if q.withTargets {
		if err := q.client.loadAppTargets(ctx, q.configureTargets, items...); err != nil {
			return err
		}
	}

	return nil
}

func (q AppQuery) Select(fields ...nook.Field[App]) AppSelect {
	return AppSelect{
		query:  q,
		fields: append([]nook.Field[App](nil), fields...),
	}
}

func (q AppQuery) IDs(ctx context.Context) ([]int64, error) {
	projections, err := q.Select(AppColumns.ID).All(ctx)
	if err != nil {
		return nil, err
	}
	ids := make([]int64, len(projections))
	for i, item := range projections {

		ids[i], err = item.ID.Get()
		if err != nil {
			return nil, err
		}

	}

	return ids, nil
}

func (s AppSelect) All(ctx context.Context) ([]*AppProjection, error) {
	if len(s.fields) == 0 {
		return nil, errors.New("nook: Select requires fields")
	}
	names := make([]string, len(s.fields))
	seen := map[string]bool{}
	for i, field := range s.fields {
		name, err := nook.FieldName(field)
		if err != nil {
			return nil, err
		}

		if seen[name] {
			return nil, fmt.Errorf("nook: duplicate selected column %s", name)
		}
		seen[name] = true
		names[i] = name
	}
	scan := func(row interface{ Scan(...any) error }) (*AppProjection, error) {
		item := &AppProjection{}
		targets := make([]any, len(names))
		for i, name := range names {
			switch name {
			case "\"id\"":
				targets[i] = item.ID.Target()
			case "\"name\"":
				targets[i] = item.Name.Target()
			case "\"type\"":
				targets[i] = item.Type.Target()
			case "\"last_modified\"":
				targets[i] = item.LastModified.Target()
			case "\"price_change_number\"":
				targets[i] = item.PriceChangeNumber.Target()
			case "\"updated_at\"":
				targets[i] = nook.ScanTime(item.UpdatedAt.Target())
			case "\"name_fold\"":
				targets[i] = item.NameFold.Target()
			default:
				return nil, fmt.Errorf("nook: unknown selected column %s", name)
			}
		}

		if err := row.Scan(targets...); err != nil {
			return nil, err
		}

		return item, nil
	}
	query, args := nook.QuerySQL("apps", strings.Join(names, ", "), s.query.predicates, s.query.order, s.query.limit)

	return nook.ReadRows(ctx, nook.ReadExecutor(s.query.client.executor), query, args, scan)
}

