// WithTargets supports nested loading and filters. A configured Limit applies
// separately to each parent in SQL, with identity columns breaking ordering ties.
func (q AppQuery) WithTargets(configure ...func(TargetQuery) TargetQuery) AppQuery {
	callbacks := append([]func(TargetQuery) TargetQuery(nil), configure...)
	q.withTargets = true
	q.configureTargets = func(child TargetQuery) TargetQuery {
		for _, callback := range callbacks {
			if callback != nil {
				child = callback(child)
			}
		}

		return child
	}

	return q
}

