func (s DeliverySelect) All(ctx context.Context) ([]*DeliveryProjection, error) {
	if len(s.fields) == 0 {
		return nil, errors.New("nook: Select requires fields")
	}
	names := make([]string, len(s.fields))
	seen := map[string]bool{}
	for i, field := range s.fields {
		name, err := nook.FieldName(field)
		if err != nil {
			return nil, err
		}

		if seen[name] {
			return nil, fmt.Errorf("nook: duplicate selected column %s", name)
		}
		seen[name] = true
		names[i] = name
	}
	scan := func(row interface{ Scan(...any) error }) (*DeliveryProjection, error) {
		item := &DeliveryProjection{}
		targets := make([]any, len(names))
		for i, name := range names {
			switch name {
			case "\"id\"":
				targets[i] = item.ID.Target()
			case "\"event_id\"":
				targets[i] = item.EventID.Target()
			case "\"destination_id\"":
				targets[i] = item.DestinationID.Target()
			case "\"status\"":
				targets[i] = item.Status.Target()
			case "\"attempt_count\"":
				targets[i] = item.AttemptCount.Target()
			case "\"next_attempt_at\"":
				targets[i] = nook.ScanTime(item.NextAttemptAt.Target())
			case "\"message_id\"":
				targets[i] = item.MessageID.Target()
			case "\"last_error\"":
				targets[i] = item.LastError.Target()
			case "\"created_at\"":
				targets[i] = nook.ScanTime(item.CreatedAt.Target())
			case "\"updated_at\"":
				targets[i] = nook.ScanTime(item.UpdatedAt.Target())
			default:
				return nil, fmt.Errorf("nook: unknown selected column %s", name)
			}
		}

		if err := row.Scan(targets...); err != nil {
			return nil, err
		}

		return item, nil
	}
	query, args := nook.QuerySQL("deliveries", strings.Join(names, ", "), s.query.predicates, s.query.order, s.query.limit)

	return nook.ReadRows(ctx, nook.ReadExecutor(s.query.client.executor), query, args, scan)
}

