// WithEvent supports nested loading and filters. A configured Limit applies
// separately to each parent in SQL, with identity columns breaking ordering ties.
func (q DeliveryQuery) WithEvent(configure ...func(EventQuery) EventQuery) DeliveryQuery {
	callbacks := append([]func(EventQuery) EventQuery(nil), configure...)
	q.withEvent = true
	q.configureEvent = func(child EventQuery) EventQuery {
		for _, callback := range callbacks {
			if callback != nil {
				child = callback(child)
			}
		}

		return child
	}

	return q
}

