func (s EventSelect) All(ctx context.Context) ([]*EventProjection, error) {
	if len(s.fields) == 0 {
		return nil, errors.New("nook: Select requires fields")
	}
	names := make([]string, len(s.fields))
	seen := map[string]bool{}
	for i, field := range s.fields {
		name, err := nook.FieldName(field)
		if err != nil {
			return nil, err
		}

		if seen[name] {
			return nil, fmt.Errorf("nook: duplicate selected column %s", name)
		}
		seen[name] = true
		names[i] = name
	}
	scan := func(row interface{ Scan(...any) error }) (*EventProjection, error) {
		item := &EventProjection{}
		targets := make([]any, len(names))
		for i, name := range names {
			switch name {
			case "\"id\"":
				targets[i] = item.ID.Target()
			case "\"rule_id\"":
				targets[i] = item.RuleID.Target()
			case "\"observation_id\"":
				targets[i] = item.ObservationID.Target()
			case "\"payload\"":
				targets[i] = item.Payload.Target()
			case "\"created_at\"":
				targets[i] = nook.ScanTime(item.CreatedAt.Target())
			default:
				return nil, fmt.Errorf("nook: unknown selected column %s", name)
			}
		}

		if err := row.Scan(targets...); err != nil {
			return nil, err
		}

		return item, nil
	}
	query, args := nook.QuerySQL("events", strings.Join(names, ", "), s.query.predicates, s.query.order, s.query.limit)

	return nook.ReadRows(ctx, nook.ReadExecutor(s.query.client.executor), query, args, scan)
}

