// Save creates the whole batch atomically. Defaults and validation run for each row.
func (b *EventBulk) Save(ctx context.Context) ([]*Event, error) {
	if _, err := b.conflictSQL(); err != nil {
		return nil, err
	}
	items := make([]*Event, 0, len(b.inputs))
	if len(b.inputs) == 0 {
		return items, nil
	}
	err := nook.Atomic(ctx, b.client.executor, func(executor nook.Executor) error {
		client := New(executor)
		for _, input := range b.inputs {
			builder := client.Event.Create().Input(input)
			if b.upsert {
				builder.OnConflict(b.conflict...).ConflictWhere(b.predicate)
				if len(b.incoming) > 0 {
					builder.UpdateExcluded(b.incoming...)
				}
			}
			item, err := builder.Save(ctx)
			if err != nil {
				return err
			}
			items = append(items, item)
		}

		return nil
	})
	if err != nil {
		return nil, err
	}

	return items, nil
}

// Exec is atomic across internal chunks. Repeated conflict keys are processed
// in input order. Save returns one slot per input, with nil for DO NOTHING.
func (b *EventBulk) Exec(ctx context.Context) (int64, error) {
	conflict, err := b.conflictSQL()
	if err != nil {
		return 0, err
	}

	if len(b.inputs) == 0 {
		return 0, nil
	}
	var count int64
	err = nook.Atomic(ctx, b.client.executor, func(executor nook.Executor) error {
		prepare := func(i int) (nook.InsertRow, error) {
			input := b.inputs[i]
			row := nook.InsertRow{}
			var err error

			input.ID, err = nook.Prepare(input.ID, ruleEventID, runtimeBehaviors["events.id"], true)
			if err != nil {
				return row, err
			}

			if err := input.ID.Append("id", false, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			input.RuleID, err = nook.Prepare(input.RuleID, ruleEventRuleID, runtimeBehaviors["events.rule_id"], true)
			if err != nil {
				return row, err
			}

			if err := input.RuleID.Append("rule_id", false, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			input.ObservationID, err = nook.Prepare(input.ObservationID, ruleEventObservationID, runtimeBehaviors["events.observation_id"], true)
			if err != nil {
				return row, err
			}

			if err := input.ObservationID.Append("observation_id", false, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			input.Payload, err = nook.Prepare(input.Payload, ruleEventPayload, runtimeBehaviors["events.payload"], true)
			if err != nil {
				return row, err
			}

			if err := input.Payload.Append("payload", false, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			input.CreatedAt, err = nook.Prepare(input.CreatedAt, ruleEventCreatedAt, runtimeBehaviors["events.created_at"], true)
			if err != nil {
				return row, err
			}

			if err := input.CreatedAt.Append("created_at", false, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			return row, nil
		}
		var err error
		count, err = nook.InsertBatchCount(ctx, executor, "events", len(b.inputs), prepare, conflict, "\"id\", \"payload\", \"created_at\"", scanCountEvent)

		return err
	})
	if err != nil {
		return 0, err
	}

	return count, nil
}

