func (c *Client) loadEventDeliveries(ctx context.Context, configure func(DeliveryQuery) DeliveryQuery, items ...*Event) error {
	ids := make([][]any, 0, len(items))
	seen := make(map[string]bool, len(items))
	for _, item := range items {
		if item == nil {
			return errors.New("nook: nil entity passed to relationship loader")
		}

		key := keyEvent(item)
		if !seen[key] {
			seen[key] = true
			ids = append(ids, nook.KeyValues(key))
		}
	}
	query := c.Delivery.Query()
	if configure != nil {
		query = configure(query)
	}
	// Always execute through the parent's transaction, even if a callback returns another query.
	query.client = c
	if query.limit >= 0 {
		grouped := make(map[string][]*Delivery, len(ids))
		batchSize := max(1, 500/1)
		for start := 0; start < len(ids) && query.limit != 0; start += batchSize {
			batchIDs := ids[start:min(start+batchSize, len(ids))]
			groups, children, err := nook.SelectRelatedLimited(ctx, c.executor, nook.Relation{
				Kind:           "has_many",
				SourceTable:    "events",
				SourceKeys:     []string{"id"},
				TargetTable:    "deliveries",
				TargetKeys:     []string{"id"},
				ForeignKeys:    []string{"event_id"},
				Through:        "",
				ThroughTargets: []string{""},
			}, []string{"id", "event_id", "destination_id", "status", "attempt_count", "next_attempt_at", "message_id", "last_error", "created_at", "updated_at"}, batchIDs, query.predicates, query.order, query.limit, scanDelivery)
			if err != nil {
				return err
			}

			if err := query.loadRelations(ctx, children); err != nil {
				return err
			}
			for key, values := range groups {
				grouped[key] = append(grouped[key], values...)
			}
		}
		for _, item := range items {
			children := grouped[nook.KeyToken(nook.KeyValues(keyEvent(item)))]
			item.Deliveries = nook.LoadedMany(children)

		}

		return nil
	}
	// A SQL LIMIT would cap the whole batch; apply it to each parent below.
	limit := query.limit
	query.limit = -1
	if len(query.order) == 0 {
		query = query.OrderBy(DeliveryColumns.ID.Asc())
	}
	grouped := make(map[string][]*Delivery, len(ids))
	relation := nook.Relation{
		Kind:           "has_many",
		SourceTable:    "events",
		SourceKeys:     []string{"id"},
		TargetTable:    "deliveries",
		TargetKeys:     []string{"id"},
		ForeignKeys:    []string{"event_id"},
		Through:        "",
		ThroughTargets: []string{""},
	}
	// Each key component uses a bind parameter, so wider keys need smaller batches.
	batchSize := max(1, 500/1)
	for start := 0; start < len(ids) && limit != 0; start += batchSize {
		batchIDs := ids[start:min(start+batchSize, len(ids))]
		children, err := query.Where(nook.RelatedKeyTargets[Delivery](relation, batchIDs...)).All(ctx)
		if err != nil {
			return err
		}

		for _, child := range children {

			parent := child.EventID

			if limit < 0 || len(grouped[parent]) < limit {
				grouped[parent] = append(grouped[parent], child)
			}

		}
	}

	for _, item := range items {
		item.Deliveries = nook.LoadedMany(grouped[keyEvent(item)])

	}

	return nil
}

