// WithTarget supports nested loading and filters. A configured Limit applies
// separately to each parent in SQL, with identity columns breaking ordering ties.
func (q ObservationQuery) WithTarget(configure ...func(TargetQuery) TargetQuery) ObservationQuery {
	callbacks := append([]func(TargetQuery) TargetQuery(nil), configure...)
	q.withTarget = true
	q.configureTarget = func(child TargetQuery) TargetQuery {
		for _, callback := range callbacks {
			if callback != nil {
				child = callback(child)
			}
		}

		return child
	}

	return q
}

