func (c *Client) loadObservationTarget(ctx context.Context, configure func(TargetQuery) TargetQuery, items ...*Observation) error {
	ids := make([][]any, 0, len(items))
	seen := make(map[string]bool, len(items))
	for _, item := range items {
		if item == nil {
			return errors.New("nook: nil entity passed to relationship loader")
		}

		key := keyObservation(item)
		if !seen[key] {
			seen[key] = true
			ids = append(ids, nook.KeyValues(key))
		}
	}
	query := c.Target.Query()
	if configure != nil {
		query = configure(query)
	}
	// Always execute through the parent's transaction, even if a callback returns another query.
	query.client = c
	if query.limit >= 0 {
		grouped := make(map[string][]*Target, len(ids))
		batchSize := max(1, 500/1)
		for start := 0; start < len(ids) && query.limit != 0; start += batchSize {
			batchIDs := ids[start:min(start+batchSize, len(ids))]
			groups, children, err := nook.SelectRelatedLimited(ctx, c.executor, nook.Relation{
				Kind:           "belongs_to",
				SourceTable:    "observations",
				SourceKeys:     []string{"id"},
				TargetTable:    "targets",
				TargetKeys:     []string{"id"},
				ForeignKeys:    []string{"target_id"},
				Through:        "",
				ThroughTargets: []string{""},
			}, []string{"id", "app_id", "country", "next_due_at", "last_observed_at", "failure_count", "last_error"}, batchIDs, query.predicates, query.order, query.limit, scanTarget)
			if err != nil {
				return err
			}

			if err := query.loadRelations(ctx, children); err != nil {
				return err
			}
			for key, values := range groups {
				grouped[key] = append(grouped[key], values...)
			}
		}
		for _, item := range items {
			children := grouped[nook.KeyToken(nook.KeyValues(keyObservation(item)))]

			if len(children) > 1 {
				return nook.ErrNotSingular
			}
			var child *Target
			if len(children) == 1 {
				child = children[0]
			}
			item.Target = nook.LoadedOne(child)

		}

		return nil
	}
	// A SQL LIMIT would cap the whole batch; apply it to each parent below.
	limit := query.limit
	query.limit = -1
	if len(query.order) == 0 {
		query = query.OrderBy(TargetColumns.ID.Asc())
	}
	grouped := make(map[string][]*Target, len(ids))
	relation := nook.Relation{
		Kind:           "belongs_to",
		SourceTable:    "observations",
		SourceKeys:     []string{"id"},
		TargetTable:    "targets",
		TargetKeys:     []string{"id"},
		ForeignKeys:    []string{"target_id"},
		Through:        "",
		ThroughTargets: []string{""},
	}
	// Each key component uses a bind parameter, so wider keys need smaller batches.
	batchSize := max(1, 500/1)
	for start := 0; start < len(ids) && limit != 0; start += batchSize {
		batchIDs := ids[start:min(start+batchSize, len(ids))]
		parents, err := nook.RelationKeyPairs(ctx, nook.ReadExecutor(c.executor), relation, batchIDs)
		if err != nil {
			return err
		}

		if len(parents) == 0 {
			continue
		}
		children, err := query.Where(nook.RelatedKeyTargets[Target](relation, batchIDs...)).All(ctx)
		if err != nil {
			return err
		}

		for _, child := range children {
			for _, parent := range parents[nook.KeyToken(nook.KeyValues(keyTarget(child)))] {

				if limit < 0 || len(grouped[parent]) < limit {
					grouped[parent] = append(grouped[parent], child)
				}
			}
		}
	}

	for _, item := range items {

		children := grouped[nook.KeyToken(nook.KeyValues(keyObservation(item)))]
		if len(children) > 1 {
			return nook.ErrNotSingular
		}
		var child *Target
		if len(children) == 1 {
			child = children[0]
		}
		item.Target = nook.LoadedOne(child)

	}

	return nil
}

