func (q RuleQuery) First(ctx context.Context) (*Rule, error) {
	items, err := q.Limit(1).All(ctx)
	if err != nil {
		return nil, err
	}

	if len(items) == 0 {
		return nil, sql.ErrNoRows
	}

	return items[0], nil
}

// Only checks cardinality independently of an existing Limit.
func (q RuleQuery) Only(ctx context.Context) (*Rule, error) {
	items, err := q.Limit(2).All(ctx)
	if err != nil {
		return nil, err
	}

	if len(items) == 0 {
		return nil, sql.ErrNoRows
	}

	if len(items) != 1 {
		return nil, nook.ErrNotSingular
	}

	return items[0], nil
}

