func (q RuleQuery) IDs(ctx context.Context) ([]string, error) {
	projections, err := q.Select(RuleColumns.ID).All(ctx)
	if err != nil {
		return nil, err
	}
	ids := make([]string, len(projections))
	for i, item := range projections {

		ids[i], err = item.ID.Get()
		if err != nil {
			return nil, err
		}

	}

	return ids, nil
}

func (s RuleSelect) All(ctx context.Context) ([]*RuleProjection, error) {
	if len(s.fields) == 0 {
		return nil, errors.New("nook: Select requires fields")
	}
	names := make([]string, len(s.fields))
	seen := map[string]bool{}
	for i, field := range s.fields {
		name, err := nook.FieldName(field)
		if err != nil {
			return nil, err
		}

		if seen[name] {
			return nil, fmt.Errorf("nook: duplicate selected column %s", name)
		}
		seen[name] = true
		names[i] = name
	}
	scan := func(row interface{ Scan(...any) error }) (*RuleProjection, error) {
		item := &RuleProjection{}
		targets := make([]any, len(names))
		for i, name := range names {
			switch name {
			case "\"id\"":
				targets[i] = item.ID.Target()
			case "\"target_id\"":
				targets[i] = item.TargetID.Target()
			case "\"owner_id\"":
				targets[i] = item.OwnerID.Target()
			case "\"request_id\"":
				targets[i] = item.RequestID.Target()
			case "\"condition\"":
				targets[i] = item.Condition.Target()
			case "\"budget_minor\"":
				targets[i] = item.BudgetMinor.Target()
			case "\"budget_currency\"":
				targets[i] = item.BudgetCurrency.Target()
			case "\"recurring\"":
				targets[i] = item.Recurring.Target()
			case "\"enabled\"":
				targets[i] = item.Enabled.Target()
			case "\"latched\"":
				targets[i] = item.Latched.Target()
			case "\"created_at\"":
				targets[i] = nook.ScanTime(item.CreatedAt.Target())
			case "\"updated_at\"":
				targets[i] = nook.ScanTime(item.UpdatedAt.Target())
			default:
				return nil, fmt.Errorf("nook: unknown selected column %s", name)
			}
		}

		if err := row.Scan(targets...); err != nil {
			return nil, err
		}

		return item, nil
	}
	query, args := nook.QuerySQL("rules", strings.Join(names, ", "), s.query.predicates, s.query.order, s.query.limit)

	return nook.ReadRows(ctx, nook.ReadExecutor(s.query.client.executor), query, args, scan)
}

