// Exec is atomic across internal chunks. Repeated conflict keys are processed
// in input order. Save returns one slot per input, with nil for DO NOTHING.
func (b *TargetBulk) Exec(ctx context.Context) (int64, error) {
	conflict, err := b.conflictSQL()
	if err != nil {
		return 0, err
	}

	if len(b.inputs) == 0 {
		return 0, nil
	}
	var count int64
	err = nook.Atomic(ctx, b.client.executor, func(executor nook.Executor) error {
		prepare := func(i int) (nook.InsertRow, error) {
			input := b.inputs[i]
			row := nook.InsertRow{}
			var err error

			input.ID, err = nook.Prepare(input.ID, ruleTargetID, runtimeBehaviors["targets.id"], true)
			if err != nil {
				return row, err
			}

			if err := input.ID.Append("id", false, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			input.AppID, err = nook.Prepare(input.AppID, ruleTargetAppID, runtimeBehaviors["targets.app_id"], true)
			if err != nil {
				return row, err
			}

			if err := input.AppID.Append("app_id", false, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			input.Country, err = nook.Prepare(input.Country, ruleTargetCountry, runtimeBehaviors["targets.country"], true)
			if err != nil {
				return row, err
			}

			if err := input.Country.Append("country", false, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			input.NextDueAt, err = nook.Prepare(input.NextDueAt, ruleTargetNextDueAt, runtimeBehaviors["targets.next_due_at"], true)
			if err != nil {
				return row, err
			}

			if err := input.NextDueAt.Append("next_due_at", false, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			input.LastObservedAt, err = nook.Prepare(input.LastObservedAt, ruleTargetLastObservedAt, runtimeBehaviors["targets.last_observed_at"], true)
			if err != nil {
				return row, err
			}

			if err := input.LastObservedAt.Append("last_observed_at", true, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			input.FailureCount, err = nook.Prepare(input.FailureCount, ruleTargetFailureCount, runtimeBehaviors["targets.failure_count"], true)
			if err != nil {
				return row, err
			}

			if err := input.FailureCount.Append("failure_count", false, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			input.LastError, err = nook.Prepare(input.LastError, ruleTargetLastError, runtimeBehaviors["targets.last_error"], true)
			if err != nil {
				return row, err
			}

			if err := input.LastError.Append("last_error", false, &row.Columns, &row.Values); err != nil {
				return row, err
			}

			return row, nil
		}
		var err error
		count, err = nook.InsertBatchCount(ctx, executor, "targets", len(b.inputs), prepare, conflict, "\"id\", \"country\", \"next_due_at\", \"last_observed_at\"", scanCountTarget)

		return err
	})
	if err != nil {
		return 0, err
	}

	return count, nil
}

